package com.portfolio.features.education.service; import com.portfolio.common.exception.NotFoundException; import com.portfolio.features.education.dto.*; import com.portfolio.features.education.entity.Education; import com.portfolio.features.education.repository.EducationRepository; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class EducationService {private final EducationRepository repo;private final PortfolioAccessService access;@Transactional(readOnly=true) public List<Education> list(AppUser u){return repo.findByPortfolioIdOrderBySortOrderAscStartDateDesc(access.mine(u).getId());}@Transactional public Education create(AppUser u,EducationRequest r){Education e=new Education();e.setPortfolio(access.mine(u));apply(e,r);return repo.save(e);}@Transactional public Education update(AppUser u,UUID id,EducationRequest r){Education e=owned(u,id);apply(e,r);return e;}@Transactional public void delete(AppUser u,UUID id){repo.delete(owned(u,id));}private Education owned(AppUser u,UUID id){Education e=repo.findById(id).orElseThrow(()->new NotFoundException("Education not found."));access.owned(u,e.getPortfolio().getId());return e;}private void apply(Education e,EducationRequest r){e.setSchool(r.school().trim());e.setDegree(r.degree());e.setMajor(r.major());e.setStartDate(r.startDate());e.setEndDate(r.endDate());e.setDescription(r.description());e.setSortOrder(r.sortOrder());}}
